using Humanizer;

// Strings
"post_title".Humanize(); // "Post title"
"CanReturnHtml".Humanize(LetterCasing.Title); // "Can Return Html"

// Dates
DateTime.UtcNow.AddDays(-1).Humanize(); // "yesterday"
DateTime.UtcNow.AddHours(-3).Humanize(); // "3 hours ago"

// TimeSpan
TimeSpan.FromDays(5).Humanize(); // "5 days"
TimeSpan.FromMinutes(90).Humanize(precision: 1); // "an hour and a half"

// Numbers
12345.ToWords(); // "twelve thousand three hundred forty-five"

// Enums
public enum OrderStatus { Pending, Processing, Shipped, Delivered }
OrderStatus.Shipped.Humanize(); // "shipped"
